from functools import lru_cache
from fractions import Fraction as Q
from math import factorial, comb
import sympy as s

@lru_cache(None)
def b(g):
    if g==0:return Q(1)
    return Q((-1)**(g-1)*(2**(2*g-1)-1),2**(2*g-1))*Q(s.bernoulli(2*g))/factorial(2*g)

def splits(t):
    # multiset subsets: (selected, complement, binomial multiplicity)
    from collections import Counter
    items=list(Counter(t).items())
    def rec(i,a,c,m):
        if i==len(items):yield tuple(a),tuple(c),m;return
        v,n=items[i]
        for k in range(n+1):yield from rec(i+1,a+[v]*k,c+[v]*(n-k),m*comb(n,k))
    return rec(0,[],[],1)

@lru_cache(None)
def F(g,ds,ms):
    ds=tuple(sorted(ds));ms=tuple(sorted(ms))
    n=len(ds)
    if 2*g-2+n<=0:return Q(0)
    if sum(ds)+sum(ms)!=2*g-3+n:return Q(0)
    if g==0:
        if ms:return Q(0)
        return Q(factorial(n-3),__import__('math').prod(factorial(x) for x in ds))
    if not ms:
        return b(g)*factorial(sum(ds))/__import__('math').prod(factorial(x) for x in ds)
    m,*rest=ms;rest=tuple(rest)
    value=F(g,tuple(sorted(ds+(m+1,))),rest)
    from collections import Counter
    for d,num in Counter(ds).items():
        dd=list(ds);dd.remove(d);dd.append(d+m)
        value-=num*F(g,tuple(sorted(dd)),rest)
    boundary=Q(0)
    for ga in range(g+1):
      gb=g-ga
      for da,db,multd in splits(ds):
        if 2*ga-1+len(da)<=0 or 2*gb-1+len(db)<=0:continue
        for ma,mb,multm in splits(rest):
          # dimension forces node exponent j
          j=2*ga-2+len(da)-sum(da)-sum(ma)
          if 0<=j<m:
            boundary+=(-1)**j*multd*multm*F(ga,tuple(sorted(da+(j,))),ma)*F(gb,tuple(sorted(db+(m-1-j,))),mb)
    value+=boundary/2
    return Q(s.bernoulli(m+1))/factorial(m+1)*value

if __name__=='__main__':
    # F(1,0,ch1)=int lambda1*lambda1=0 (dimension already forces zero)
    # F(2,empty,ch1)=int lambda2 lambda1=1/5760
    print('b1,b2,b3',b(1),b(2),b(3))
    print('lambda2 lambda1',F(2,(),(1,)),Q(1,5760))
    print('lambda3 lambda2 via ch1^2/2',F(3,(),(1,1))/2, Q(1,1451520))
    print(F.cache_info())

